def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    MIN_SUPPLY = 15
    MAX_SUPPLY = 25

    budget = my_status['budget']
    hp = my_status['hp']
    no_water = my_status['no_water_days']
    supply = day_context['supply']
    day = day_context['day']

    if budget <= 0:
        return 0.0

    alive = []
    for agent_id, opp in opponents_status.items():
        if opp.get('alive'):
            alive.append(opp)

    if not alive:
        bid = min(budget, DAILY_SALARY * 0.35)
        return max(0.0, bid)

    prev_bids = []
    danger_bids = []
    rich_aggressive = 0
    desperate_count = 0

    for opp in alive:
        prev = opp.get('previous_trace', {})
        if prev and prev.get('bid') is not None:
            pbid = prev['bid']
            prev_bids.append(pbid)
            if pbid >= DAILY_SALARY * 1.8:
                rich_aggressive += 1
            if opp.get('hp', 10) <= 3 or opp.get('no_water_days', 0) >= 1:
                danger_bids.append(max(pbid, DAILY_SALARY * 1.2))
        if opp.get('hp', 10) <= 3 or opp.get('no_water_days', 0) >= 1:
            desperate_count += 1

    highest_prev = max(prev_bids) if prev_bids else 0.0
    pressure_bid = max(danger_bids) if danger_bids else highest_prev

    supply_ratio = (supply - MIN_SUPPLY) / float(MAX_SUPPLY - MIN_SUPPLY)
    if supply_ratio < 0:
        supply_ratio = 0.0
    if supply_ratio > 1:
        supply_ratio = 1.0

    scarcity = 1.0 - supply_ratio

    if hp <= 2 or no_water >= 2:
        base = max(DAILY_SALARY * 1.1, pressure_bid + 6.0)
    elif hp <= 4 or no_water >= 1:
        base = max(DAILY_SALARY * (0.85 + 0.45 * scarcity), pressure_bid * 0.72 + 3.0)
    else:
        if supply >= 22:
            base = DAILY_SALARY * 0.28
        elif supply >= 19:
            base = DAILY_SALARY * 0.42
        else:
            base = DAILY_SALARY * 0.62

        if highest_prev > 0:
            if highest_prev >= 150:
                base = min(base, DAILY_SALARY * 0.48)
            elif highest_prev >= 100:
                base = max(base, DAILY_SALARY * 0.52)
            else:
                base = max(base, highest_prev + 2.0)

    if desperate_count >= 2 and hp > 4 and no_water == 0:
        base *= 0.9

    if rich_aggressive >= 2 and hp > 4 and supply >= 19:
        base *= 0.88

    if day >= 8 and hp > 5 and no_water == 0:
        base *= 0.92

    reserve_floor = 0.0
    if hp > 4:
        reserve_floor = DAILY_SALARY * 1.2
    elif hp > 2:
        reserve_floor = DAILY_SALARY * 0.6

    max_affordable = budget
    if budget > reserve_floor:
        max_affordable = budget - reserve_floor + min(reserve_floor, DAILY_SALARY * 0.35)

    if hp <= 2 or no_water >= 2:
        max_affordable = budget

    bid = min(base, max_affordable, budget)

    if bid < 0:
        bid = 0.0

    if hp <= 3 and bid < DAILY_SALARY * 0.75 and budget >= DAILY_SALARY * 0.75:
        bid = DAILY_SALARY * 0.75

    if bid > budget:
        bid = budget

    return float(max(0.0, bid))

