def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 150
    EPISODE_DAYS = 10

    current_day = day_context['day']
    current_supply = day_context['supply']

    strong_opponents_ids = ["Alex", "Eric"]

    alive_opponents_data = []
    strong_alive_opponents_data = []

    for opp_id, opp_data in opponents_status.items():
        if opp_data['alive']:
            alive_opponents_data.append(opp_data)
            if opp_id in strong_opponents_ids:
                strong_alive_opponents_data.append(opp_data)

    if not alive_opponents_data:
        return min(my_status['budget'], DAILY_SALARY * 0.1)

    yesterday_bids = []
    for opp_data in alive_opponents_data:
        prev = opp_data.get('previous_trace', {})
        if prev and prev.get('bid') is not None:
            yesterday_bids.append(prev['bid'])

    base_bid = DAILY_SALARY * 0.5

    if my_status['hp'] <= 2:
        base_bid = DAILY_SALARY * 0.95
    elif my_status['hp'] <= 4:
        base_bid = DAILY_SALARY * 0.75

    if yesterday_bids:
        highest_prev_bid = max(yesterday_bids)

        if highest_prev_bid >= DAILY_SALARY * 0.80:
            if my_status['hp'] > 5 and current_day < EPISODE_DAYS * 0.7:
                base_bid = min(base_bid, DAILY_SALARY * 0.4)
            else:
                base_bid = max(base_bid, highest_prev_bid + 5)
        else:
            base_bid = max(base_bid, highest_prev_bid + 2)

    num_possible_winners = int(current_supply // WATER_REQ)

    if num_possible_winners == 1:
        if len(strong_alive_opponents_data) > 0:
            base_bid = max(base_bid, DAILY_SALARY * 0.9)
            if my_status['hp'] <= 3:
                base_bid = max(base_bid, DAILY_SALARY * 0.99)
        elif len(alive_opponents_data) > 1:
             base_bid = max(base_bid, DAILY_SALARY * 0.7)

    elif num_possible_winners >= 2:
        if my_status['hp'] > 3:
            base_bid = min(base_bid, DAILY_SALARY * 0.8)

    final_bid = max(1.0, min(my_status['budget'], base_bid))

    return round(final_bid, 2)

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 8
    DAILY_SALARY = 140
    MAX_SUPPLY = 25
    MIN_SUPPLY = 15

    supply = float(day_context.get('supply', 0.0))
    day = int(day_context.get('day', 0))

    my_hp = int(my_status.get('hp', 0))
    my_budget = float(my_status.get('budget', 0.0))
    my_no_water_days = int(my_status.get('no_water_days', 0))

    alive_opps = []
    for opp_id, opp in opponents_status.items():
        if opp.get('alive', False):
            alive_opps.append((opp_id, opp))

    if not alive_opps:
        return max(0.0, min(my_budget, DAILY_SALARY * 0.4))

    # Read yesterday trace bids
    prev_bids = []
    for _, opp in alive_opps:
        prev = opp.get('previous_trace', {}) or {}
        bid = prev.get('bid', None)
        if bid is not None:
            try:
                prev_bids.append(float(bid))
            except Exception:
                pass

    highest_prev_bid = max(prev_bids) if prev_bids else 0.0

    # Estimate how many full water-units the supply can cover (approx)
    # Use integer indices safely (though we don't index lists here)
    units = int(supply / float(WATER_REQ)) if WATER_REQ > 0 else 0

    # Base bid: if supply is high enough, we can be a bit cheaper than top bidder.
    # If supply is tight, we must compete more.
    if supply >= 21:
        target = 0.65 * highest_prev_bid if highest_prev_bid > 0 else DAILY_SALARY * 0.55
    elif supply >= 17:
        target = 0.85 * highest_prev_bid if highest_prev_bid > 0 else DAILY_SALARY * 0.65
    else:
        target = 0.95 * highest_prev_bid if highest_prev_bid > 0 else DAILY_SALARY * 0.85

    # If I'm in danger, ramp up aggressively.
    if my_hp <= 2 or my_no_water_days >= 2:
        target = max(target, DAILY_SALARY * 0.9)
    elif my_hp <= 4:
        target = max(target, DAILY_SALARY * 0.7)

    # If opponents were bidding very high yesterday, avoid overpaying unless necessary.
    if highest_prev_bid >= DAILY_SALARY * 0.85:
        if my_hp >= 5 and my_no_water_days <= 1:
            target = min(target, DAILY_SALARY * 0.75)

    # Clamp to budget and non-negative
    bid = max(0.0, min(my_budget, float(target)))
    return bid
